; DSYS.S - SYSTEM PAGE RENDERER
;
; QUERIES DOS_GET_SYSTEM_INFO ($5C) EXACTLY ONCE PER REDRAW AND RENDERS THE
; VALIDATED SNAPSHOT WITH THE WP5 BOUNDED SCREEN PRIMITIVES (SCREENSETCURSOR/
; SCREENPUTSTRING/SCREENPUTCHAR), NOT THE OLD UNBOUNDED PRINTAT. NEVER READS
; PRIVATE OS MEMORY (CURRENTDEVICE, KERNALVIDEOSTD, APTSEG, MCT, VMM STATE)
; DIRECTLY -- ALL DATA COMES FROM THE PUBLIC $5C RECORD.

; QUERYSYSTEMINFO - FILLS SYSINFOBUF FROM DOS_GET_SYSTEM_INFO ($5C).
;
; INPUT: NONE. OUTPUT: C CLEAR = SUCCESS, SYSINFOBUF HOLDS A FRESH 24-BYTE
;        RECORD. C SET = FAILURE, A = OS ERROR CODE, SYSINFOBUF UNCHANGED
;        (THE OS GUARANTEES NO PARTIAL WRITE ON FAILURE).
; CLOBBERS: A, X, Y.
QUERYSYSTEMINFO:
    LDX #<SYSINFOBUF
    LDY #>SYSINFOBUF
    LDA #$5C                ; DOS_GET_SYSTEM_INFO
    JSR $1000
    RTS

; PRINTDEC16 - FORMATS X/Y (16-BIT VALUE) AS TRIMMED DECIMAL AND WRITES IT AT
; THE CURSOR (ZP $72/$77), ADVANCING THE COLUMN BY THE DIGITS WRITTEN.
;
; FORMATDEC16 (DFMT.S) ALWAYS PRODUCES A FIXED 5-BYTE SPACE-PADDED FIELD, NOT
; A TERMINATED STRING -- FINE FOR A GRID BUT NOT FOR AN INLINE SENTENCE, SO
; THIS SKIPS THE LEADING PAD SPACES (NEVER PAST INDEX 4, SO A VALUE OF 0
; STILL PRINTS "0") BEFORE WRITING THE REMAINING DIGITS ONE CHARACTER AT A
; TIME VIA SCREENPUTCHAR (WHICH PRESERVES X), RATHER THAN COMPUTING A
; FMTBUF+SKIP POINTER FOR SCREENPUTSTRING -- NO ADDRESS ARITHMETIC, JUST THE
; SAME INDEXED ADDRESSING THE SKIP SCAN BELOW ALREADY USES. LOCAL TO THIS
; PAGE RENDERER RATHER THAN A DFMT.S ADDITION, SO WP5'S FROZEN FORMATTING
; CONTRACT STAYS UNCHANGED.
;
; INPUT: X/Y = VALUE LOW/HIGH. CURSOR = ZP $72 (ROW), $77 (COL).
; CLOBBERS: A, X, Y.
PRINTDEC16:
    JSR FORMATDEC16
    LDX #0
PD16SKIP:
    LDA FMTBUF, X
    CMP #$20                 ; SPACE
    BNE PD16FOUND
    INX
    CPX #4
    BCC PD16SKIP
PD16FOUND:
    LDA FMTBUF, X
    JSR SCREENPUTCHAR
    INX
    CPX #5
    BCC PD16FOUND
    RTS

; DSYSSETROW - SETS THE CURSOR TO COLUMN 2, ROW IN A.
; INPUT: A = ROW. CLOBBERS: A, Y.
DSYSSETROW:
    TAY
    LDA #2
    JSR SCREENSETCURSOR
    RTS

DSYSRENDER:
    JSR CLEARSCREEN
    JSR DRAWFRAME

    LDA #4
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSTITLESTR
    LDY #>SYSTITLESTR
    JSR SCREENPUTSTRING

    JSR QUERYSYSTEMINFO
    BCS DSYSFAIL

    ; VALIDATE STRUCTVERSION (OFFSET 0) == 2 AND STRUCTSIZE (OFFSET 1) == 24
    ; BEFORE TRUSTING ANY FIELD (WP6: "VALIDATE STRUCTURE VERSION AND
    ; RETURNED SIZE BEFORE READING FIELDS").
    LDA SYSINFOBUF+0
    CMP #2
    BNE DSYSFAIL
    LDA SYSINFOBUF+1
    CMP #24
    BNE DSYSFAIL

    JSR DSYSROWVERSION
    JSR DSYSROWDEVICE
    JSR DSYSROWVIDEO
    JSR DSYSROWRANGE
    JSR DSYSROWPROTECTED
    JSR DSYSROWVMM
    JSR DSYSROWPGSIZE
    JSR DSYSROWPGTOTAL
    JSR DSYSROWUSEDFREE
    JSR DSYSROWAPPS
    RTS

DSYSFAIL:
    LDA #6
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSFAILSTR
    LDY #>SYSFAILSTR
    JSR SCREENPUTSTRING
    RTS

; --- OFFSET 2/3/4/22: OSMAJOR/OSMINOR/OSSTAGE/OSPATCH (ROW 6) ---
DSYSROWVERSION:
    LDA #6
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_VER
    LDY #>SYSL_VER
    JSR SCREENPUTSTRING

    LDX SYSINFOBUF+2          ; OSMAJOR
    LDY #0
    JSR PRINTDEC16
    LDA #$2E                  ; '.'
    JSR SCREENPUTCHAR

    LDX SYSINFOBUF+3          ; OSMINOR
    LDY #0
    JSR PRINTDEC16
    LDA #$2E                  ; '.'
    JSR SCREENPUTCHAR

    LDX SYSINFOBUF+22         ; OSPATCH
    LDY #0
    JSR PRINTDEC16

    ; OSSTAGE: RELEASE IS THE DEFAULT/EXPECTED CASE AND ADDS NOTHING BY
    ; SAYING SO; ONLY A DEV BUILD IS WORTH FLAGGING.
    LDA SYSINFOBUF+4          ; OSSTAGE
    BEQ DSYSVERDONE
    LDA #40
    LDX #<SYSL_DEV_STAGE
    LDY #>SYSL_DEV_STAGE
    JSR SCREENPUTSTRING
DSYSVERDONE:
    RTS

; --- OFFSET 5: CURRENTDEVICE (ROW 7) ---
DSYSROWDEVICE:
    LDA #7
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_DEVICE
    LDY #>SYSL_DEVICE
    JSR SCREENPUTSTRING

    LDX SYSINFOBUF+5
    LDY #0
    JSR PRINTDEC16
    RTS

; --- OFFSET 6: VIDEOSTANDARD (ROW 8) ---
DSYSROWVIDEO:
    LDA #8
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_VIDEO
    LDY #>SYSL_VIDEO
    JSR SCREENPUTSTRING

    LDA SYSINFOBUF+6
    CMP #0
    BEQ DSYSVIDNTSC
    CMP #1
    BEQ DSYSVIDPAL
    LDX #<SYSL_UNKNOWN
    LDY #>SYSL_UNKNOWN
    JMP DSYSVIDPRINT
DSYSVIDNTSC:
    LDX #<SYSL_NTSC
    LDY #>SYSL_NTSC
    JMP DSYSVIDPRINT
DSYSVIDPAL:
    LDX #<SYSL_PAL
    LDY #>SYSL_PAL
DSYSVIDPRINT:
    LDA #40
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 7-10: USERPROGSTART/USERPROGEND (ROW 9) ---
DSYSROWRANGE:
    LDA #9
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_RANGE
    LDY #>SYSL_RANGE
    JSR SCREENPUTSTRING

    LDX SYSINFOBUF+7          ; USERPROGSTART LOW
    LDY SYSINFOBUF+8          ; USERPROGSTART HIGH
    JSR FORMATHEX16
    LDA #40
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING

    LDA #40
    LDX #<SYSL_DASHDOLLAR
    LDY #>SYSL_DASHDOLLAR
    JSR SCREENPUTSTRING

    LDX SYSINFOBUF+9           ; USERPROGEND LOW
    LDY SYSINFOBUF+10          ; USERPROGEND HIGH
    JSR FORMATHEX16
    LDA #40
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING
    RTS

; --- STATIC (ROW 10) -- $C000-$CFFF IS DOCUMENTED, PUBLICLY-KNOWN MCT/VMM
; WORKSPACE PER THE WP1 CONTRACT, NOT A VALUE READ FROM PRIVATE OS MEMORY.
DSYSROWPROTECTED:
    LDA #10
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_PROTECTED
    LDY #>SYSL_PROTECTED
    JSR SCREENPUTSTRING
    RTS

; --- OFFSET 11: VMMFLAGS (ROW 11) ---
DSYSROWVMM:
    LDA #11
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_VMM
    LDY #>SYSL_VMM
    JSR SCREENPUTSTRING

    LDA SYSINFOBUF+11
    AND #$01                  ; BIT 0: VMM ACTIVE
    BEQ DSYSVMMINACTIVE
    LDX #<SYSL_ACTIVE
    LDY #>SYSL_ACTIVE
    JMP DSYSVMMPRINT
DSYSVMMINACTIVE:
    LDX #<SYSL_INACTIVE
    LDY #>SYSL_INACTIVE
DSYSVMMPRINT:
    LDA #40
    JSR SCREENPUTSTRING

    LDA #40
    LDX #<SYSL_REU
    LDY #>SYSL_REU
    JSR SCREENPUTSTRING

    LDA SYSINFOBUF+11
    AND #$02                  ; BIT 1: REU PROBED
    BEQ DSYSREUUNPROBED
    LDX #<SYSL_PROBED
    LDY #>SYSL_PROBED
    JMP DSYSREUPRINT
DSYSREUUNPROBED:
    LDX #<SYSL_UNPROBED
    LDY #>SYSL_UNPROBED
DSYSREUPRINT:
    LDA #40
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 12-13: VMMPAGESIZE (ROW 12) -- CAPABILITY-GATED ON VMMFLAGS BIT 0
DSYSROWPGSIZE:
    LDA #12
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_PGSIZE
    LDY #>SYSL_PGSIZE
    JSR SCREENPUTSTRING

    LDA SYSINFOBUF+11
    AND #$01
    BEQ DSYSPGSIZENA

    LDX SYSINFOBUF+12
    LDY SYSINFOBUF+13
    JSR PRINTDEC16
    LDA #40
    LDX #<SYSL_BYTES
    LDY #>SYSL_BYTES
    JSR SCREENPUTSTRING
    RTS
DSYSPGSIZENA:
    LDA #40
    LDX #<SYSL_NA
    LDY #>SYSL_NA
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 14-15: VMMTOTALPAGES (ROW 13) -- CAPABILITY-GATED
DSYSROWPGTOTAL:
    LDA #13
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_PGTOTAL
    LDY #>SYSL_PGTOTAL
    JSR SCREENPUTSTRING

    LDA SYSINFOBUF+11
    AND #$01
    BEQ DSYSPGTOTALNA

    LDX SYSINFOBUF+14
    LDY SYSINFOBUF+15
    JSR PRINTDEC16
    RTS
DSYSPGTOTALNA:
    LDA #40
    LDX #<SYSL_NA
    LDY #>SYSL_NA
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 16-19: VMMALLOCPAGES/VMMFREEPAGES (ROW 14) -- CAPABILITY-GATED
DSYSROWUSEDFREE:
    LDA #14
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_USEDFREE
    LDY #>SYSL_USEDFREE
    JSR SCREENPUTSTRING

    LDA SYSINFOBUF+11
    AND #$01
    BEQ DSYSUSEDFREENA

    LDX SYSINFOBUF+16
    LDY SYSINFOBUF+17
    JSR PRINTDEC16
    LDA #40
    LDX #<SYSL_SLASH
    LDY #>SYSL_SLASH
    JSR SCREENPUTSTRING
    LDX SYSINFOBUF+18
    LDY SYSINFOBUF+19
    JSR PRINTDEC16
    RTS
DSYSUSEDFREENA:
    LDA #40
    LDX #<SYSL_NA
    LDY #>SYSL_NA
    JSR SCREENPUTSTRING
    RTS

; --- OFFSETS 20-21: APPMAXSLOTS/APPUSEDSLOTS (ROW 15) -- ALWAYS VALID
; (APPUSEDSLOTS IS A TRUE 0 WHEN THE APP TABLE IS INACTIVE, NOT AN
; UNAVAILABLE VALUE, SO THIS IS NOT CAPABILITY-GATED)
DSYSROWAPPS:
    LDA #15
    JSR DSYSSETROW
    LDA #40
    LDX #<SYSL_APPS
    LDY #>SYSL_APPS
    JSR SCREENPUTSTRING

    LDX SYSINFOBUF+21          ; APPUSEDSLOTS
    LDY #0
    JSR PRINTDEC16
    LDA #40
    LDX #<SYSL_SLASH
    LDY #>SYSL_SLASH
    JSR SCREENPUTSTRING
    LDX SYSINFOBUF+20          ; APPMAXSLOTS
    LDY #0
    JSR PRINTDEC16
    RTS
